		return a > b;
	});

	F0R(a, n) {
		if (m[p[a]] == mp(0, 0))
			m[p[a]] = {1, 1}, asp[a] = true;
		else {
			int q = p[a] - 1;
			map<int, int> M;
			while (q != 1) {
				M[S.sp[q]]++;
				q /= S.sp[q];
			}
			trav(b, M) {
				auto temp = m[b.f];
				if (temp.f == b.s)
					m[b.f] = {temp.f, temp.s + 1};
				else if (temp.f < b.s)
					m[b.f] = {b.s, 1};
			}
		}
	}

	bool add = false;
	F0R(a, n) {
		if (asp[a]) {
			if (m[p[a]].f > 1 || m[p[a]].s > 1)
				add = true;
		} else {
			bool good = true;
			int q = p[a] - 1;
			map<int, int> M;
			while (q != 1) {
				M[S.sp[q]]++;
				q /= S.sp[q];
			}
			trav(b, M) {
				auto temp = m[b.f];
				if (!(temp.f > b.s || temp.s > 1))
					good = false;
			}
			if (good)
				add = true;
		}
	}

	ll lcm = 1;
	trav(a, m)
		lcm = (lcm * exp(a.f, a.s.f)) % MOD;

	cout << (lcm + add) % MOD << endl;
}

