struct custom_hash {
	static uint64_t splitmix64(uint64_t x) {
		x += 0x9e3779b97f4a7c15;
		x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9;
		x = (x ^ (x >> 27)) * 0x94d049bb133111eb;
		return x ^ (x >> 31);
	}

	size_t operator()(uint64_t x) const {
		static const uint64_t FIXED_RANDOM =
			chrono::steady_clock::now().time_since_epoch().count();
		return splitmix64(x + FIXED_RANDOM);
	}
};

template<int SZ> struct Sieve {
	vi pr;
	int sp[SZ];

	Sieve() {
		memset(sp,0,sizeof sp);
		FOR(i,2,SZ) {
			if (sp[i] == 0) {
				sp[i] = i;
				pr.pb(i);
			}
			trav(p,pr) {
				if (p > sp[i] || i*p >= SZ) break;
				sp[i*p] = p;
			}
		}
	}
};

Sieve<2000010> S;

ll exp(ll a, int b) {
	if (b == 0) return 1;
	ll p = exp(a, b / 2);
	p = (p * p) % MOD;
	if (b & 1) p = (p * a) % MOD;
	return p;
}

int main() {
	setIO();

	int n;
	cin >> n;

	vector<bool> asp(n);
	map<int, pi> m;
	vi p(n);

	F0R(a, n) cin >> p[a];

	sort(all(p), [](const int& a, const int& b) {
		return a > b;
	});

	F0R(a, n) {
		if (m[p[a]] == mp(0, 0)) {
			m[p[a]] = {1, 1};
			asp[a] = true;
		} else {
			int q = p[a] - 1;
			map<int, int> M;

			while (q != 1) {
				M[S.sp[q]]++;
				q /= S.sp[q];
			}

			trav(b, M) {
				auto temp = m[b.f];
				if (temp.f == b.s)
					m[b.f] = {temp.f, temp.s + 1};
				else if (temp.f < b.s)
					m[b.f] = {b.s, 1};
			}
		}
	}

	bool add = false;

	F0R(a, n) {
		if (asp[a]) {
			if (m[p[a]].f > 1 || m[p[a]].s > 1)
				add = true;
		} else {
			bool good = true;
			int q = p[a] - 1;
			map<int, int> M;

			while (q != 1) {
				M[S.sp[q]]++;
				q /= S.sp[q];
			}

			trav(b, M) {
				auto temp = m[b.f];
				if (!(temp.f > b.s || temp.s > 1))
					good = false;
			}

			if (good)
				add = true;
		}
	}

	ll lcm = 1;
	trav(a, m)
		lcm = (lcm * exp(a.f, a.s.f)) % MOD;

	cout << (lcm + add) % MOD << endl;
}

